-- Lösungswege für die Forderungskarte (ohne Punkte). Upsert, damit gespeicherte Forderungen ihren Verweis behalten.
insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft, nebenwirkungen) values
  (10227, 25, 'Plattformen zum Entfernen rechtswidriger Hassinhalte verpflichten (Bund)', 'Löschpflichten mit Bußgeld senkten nach NetzDG-Studie Hass online und Hasskriminalität offline; die Pflicht besteht über den DSA aber schon, und eigene nationale Regeln sind durch die EU-Harmonisierung begrenzt.', 'belegt', 'https://econpapers.repec.org/RePEc:cge:wacage:701', 'bund', null, true, 'blind', null),
  (10228, 25, 'Digitales Gewaltschutzgesetz mit gerichtlichen Accountsperren und Betroffenenrechten (Bund)', 'Sperren von Täterkonten senkten in Fallstudien Aktivität und Toxizität, Betroffene erhalten einen Rechtsweg; Ausweichen auf neue Konten oder andere Plattformen schwächt die Wirkung, die Belege sind begrenzt.', 'gemischt', 'https://cscw2021.cc.gatech.edu/?p=43', 'bund', null, true, 'blind', null),
  (10229, 25, 'Login-Falle zur Identifizierung anonymer Täter (Bund)', 'Schließt eine Ermittlungslücke bei anonymen Konten und macht Anzeigen aussichtsreicher; zur tatsächlichen Wirkung auf Aufklärung und Abschreckung gibt es kaum Untersuchungen.', 'offen', null, 'bund', null, true, 'blind', null),
  (10230, 25, 'Verfolgung von Hasskriminalität durch Polizei und Schwerpunktstaatsanwaltschaften stärken (Bund)', 'Spezialisierte Stellen erhöhen Fallzahlen und Verfahren, eine Wirkung auf Melde- und Anzeigeverhalten ist nicht untersucht; Polizei und Staatsanwaltschaften sind überwiegend Ländersache.', 'offen', null, 'bund', null, true, 'blind', null),
  (10231, 25, 'Beratung und Ansprechstellen für Betroffene von Hass dauerhaft fördern (Bund)', 'Beratung senkt den Aufwand für Betroffene, gegen Hass vorzugehen, Evaluationen zeigen hohe Zufriedenheit; Wirkung auf Meldungen und Anzeigen ist kaum gemessen, der Bund kann nur über Programme fördern.', 'offen', null, 'bund', null, true, 'blind', null),
  (10232, 25, 'Strafrechtliche Lücken bei Hetze und bildbasierter digitaler Gewalt schließen (Bund)', 'Neue oder klarere Straftatbestände geben Betroffenen eine Handhabe; ob sie Hass im Netz verringern, hängt von der Durchsetzung ab und ist kaum untersucht.', 'offen', null, 'bund', null, true, 'blind', null),
  (10233, 25, 'Beratung und Hilfe für Betroffene digitaler Gewalt ausbauen (Land)', 'Beratung und geschulte Fachkräfte senken die Hürden, gegen Anfeindungen vorzugehen, Evaluationen zeigen hohe Zufriedenheit; belastbare Wirkungsbelege zu Meldungen fehlen.', 'offen', null, 'land', null, true, 'blind', null),
  (10234, 25, 'Meldestellen für Hass und digitale Gewalt einrichten und fördern (Land)', 'Ein zentraler Meldeweg mit Weiterleitung an Strafverfolgung setzt direkt an der geringen Meldequote an; zur Wirkung auf Meldeverhalten und Hassaufkommen gibt es kaum Studien.', 'offen', null, 'land', null, true, 'blind', null),
  (10235, 25, 'Öffentliche Förderung von Meldestellen beenden (Land)', 'Weniger Meldewege erschweren Betroffenen das Melden; ein Beitrag zum Schutz vor Anfeindungen ist nicht erkennbar.', 'offen', null, 'land', null, true, 'blind', null),
  (10236, 25, 'Spezialisierte Verfolgung von Online-Hass bei Polizei und Staatsanwaltschaft stärken (Land)', 'Mehr Personal, Technik und Schulung erhöhen die Chance, dass Anzeigen Folgen haben; eine Wirkung auf Meldeverhalten oder Hassaufkommen ist nicht evaluiert.', 'offen', null, 'land', null, true, 'blind', null),
  (10237, 25, 'Strafrecht gegen digitale Gewalt und Deepfakes weiterentwickeln (Land, über Bundesrat)', 'Klarere Tatbestände geben Betroffenen eine Handhabe, die Wirkung ist kaum untersucht; das Strafrecht regelt der Bund, das Land kann nur über den Bundesrat anstoßen.', 'offen', null, 'land', null, true, 'blind', null),
  (10238, 25, 'Strafrechtsschutz bei Ehr- und Hassdelikten zurücknehmen (Land, über Bundesrat)', 'Weniger Strafschutz gibt Betroffenen weniger Handhabe gegen Anfeindungen; Kritiker sehen darin Schutz der Meinungsfreiheit, zum Ziel trägt es nicht bei. Zuständig ist der Bund.', 'offen', null, 'land', null, true, 'blind', null),
  (10239, 25, 'Prävention von Hass und digitaler Gewalt in Schule, Bildung und Kampagnen (Land)', 'Schulische Programme gegen Cybermobbing senkten Täterschaft in einer Meta-Analyse um 10–15 %; andere Auswertungen sind weniger eindeutig, reine Aufklärungskampagnen sind kaum untersucht.', 'gemischt', 'https://www.vrc.crim.cam.ac.uk/node/1282', 'land', null, true, 'blind', null),
  (10240, 25, 'Zivilgesellschaftliche und Demokratie-Projekte gegen Hass fördern (Land)', 'Kann Prävention und Gegenrede stärken; der Bezug zu Anfeindungen im Netz ist unbestimmt und die Wirkung solcher Förderung kaum untersucht.', 'offen', null, 'land', null, true, 'blind', null),
  (10356, 25, 'Öffentliche Förderung von Meldestellen beenden (Bund)', 'Weniger Meldewege erschweren Betroffenen das Melden; Befürworter verweisen auf Meinungsfreiheit, ein Beitrag zum Schutz vor Anfeindungen ist nicht erkennbar. Der Bund kann eigene Förderung einstellen.', 'offen', null, 'bund', null, true, 'blind', null),
  (10357, 25, 'Strafrechtsschutz bei Ehrdelikten gegen Personen des politischen Lebens zurücknehmen (Bund)', 'Weniger Strafschutz gibt Betroffenen weniger Handhabe gegen Anfeindungen; Kritiker der Norm sehen darin Schutz der Meinungsfreiheit, zum Ziel trägt es nicht bei. Der Bund kann das StGB ändern.', 'offen', null, 'bund', null, true, 'blind', null),
  (10358, 25, 'Unbestimmte Zusage, Hasskriminalität konsequent zu verfolgen (Land)', 'Strafverfolgung kann Betroffenen Rückhalt geben und abschrecken; ohne konkretes Mittel (Personal, Stellen, Meldeweg) bleibt offen, was sich ändert, die Wirkung ist kaum untersucht.', 'offen', null, 'land', null, true, 'blind', null)
