insert into public.massnahmen (id, thema_id, partei_id, land, beschreibung, ursachen_ids, instrument_id, wirksamkeit, umsetzbarkeit,
  rollen_modifikator, begruendung, beleg_programm_url, beleg_studie_url, evidenz, stand, geprueft, ki_entwurf, entwurf_herkunft, nebenwirkungen) values
  (10241, 25, 11, null, 'Digital Services Act mit Schwerpunkt auf Transparenz sowie Jugend- und Medienschutz umsetzen', '{2502}', null, 1, 3, null, 'Die DSA-Durchsetzung regelt Plattformpflichten zur Moderation; der genannte Schwerpunkt liegt auf Desinformation und Jugendschutz, Hass wird nicht gezielt adressiert.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=41', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10242, 25, 11, null, 'Verfassungsfeindliche und antisemitische Äußerungen konsequent verfolgen und ahnden', '{2501}', 10230, 1, 2, null, 'Spezialisierte Stellen erhöhen Fallzahlen und Verfahren, eine Wirkung auf Melde- und Anzeigeverhalten ist nicht untersucht; Polizei und Staatsanwaltschaften sind überwiegend Ländersache.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=45', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10243, 25, 11, 'BE', 'Strategien gegen digitale Gewalt gezielt weiterentwickeln und bestehende Beratungsangebote ausbauen', '{2501}', 10233, 2, 3, null, 'Beratung und geschulte Fachkräfte senken die Hürden, gegen Anfeindungen vorzugehen, Evaluationen zeigen hohe Zufriedenheit; belastbare Wirkungsbelege zu Meldungen fehlen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=12', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10244, 25, 11, 'BE', 'Digitale Gewalt umfassend strafrechtlich erfassen und Lücken schließen, auch bei Mobbing in Sozialen Medien und Deepfakes', '{2501}', 10237, 1, 1, null, 'Klarere Tatbestände geben Betroffenen eine Handhabe, die Wirkung ist kaum untersucht; das Strafrecht regelt der Bund, das Land kann nur über den Bundesrat anstoßen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=12', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10245, 25, 11, 'BE', 'Spezialisierte Staatsanwaltschafts-Abteilung für Hasskriminalität ausbauen und stärken', '{2501}', 10236, 1, 3, null, 'Mehr Personal, Technik und Schulung erhöhen die Chance, dass Anzeigen Folgen haben; eine Wirkung auf Meldeverhalten oder Hassaufkommen ist nicht evaluiert.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=22', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10246, 25, 11, 'BE', 'Antisemitische Hetze konsequent verfolgen und bestrafen', '{2501}', 10236, 1, 3, null, 'Mehr Personal, Technik und Schulung erhöhen die Chance, dass Anzeigen Folgen haben; eine Wirkung auf Meldeverhalten oder Hassaufkommen ist nicht evaluiert.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=22', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10247, 25, 11, 'MV', 'Vorratsdatenspeicherung auf Bundesebene einfordern, unter anderem zur Bekämpfung von Hasskriminalität im Internet', '{2501}', null, 1, 1, null, 'Soll Täter im Netz identifizierbar machen; das MPI-Gutachten fand keinen messbaren Effekt auf Aufklärungsquoten, Ermittler verweisen auf Einzelfälle. EU-Recht setzt enge Grenzen, zuständig ist der Bund.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=35', 'https://winfuture.de/news,67824.html', 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10248, 25, 11, 'MV', 'Strafrecht gegen digitale sexualisierte Gewalt mit KI (Deepfakes) weiterentwickeln', '{2501}', 10237, 1, 1, null, 'Klarere Tatbestände geben Betroffenen eine Handhabe, die Wirkung ist kaum untersucht; das Strafrecht regelt der Bund, das Land kann nur über den Bundesrat anstoßen.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=35', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10249, 25, 11, 'MV', 'Gesetzliche Klarnamen- und ID-Pflicht gegenüber Plattformbetreibern und Anbietern digitaler Dienste', '{2503}', null, 1, 1, null, 'Soll Hemmschwellen erhöhen; Studien sind uneinheitlich, in deutschen Petitionsdaten waren Kommentare mit Klarnamen sogar aggressiver. EU-Recht (DSA, Herkunftslandprinzip) und Bundeszuständigkeit stehen entgegen.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=38', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC4912099/', 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10250, 25, 11, 'MV', 'Klare Haltung gegen Hass als Pflichtbestandteil schulischer Erziehung', '{2503}', 10239, 2, 3, null, 'Schulische Programme gegen Cybermobbing senkten Täterschaft in einer Meta-Analyse um 10–15 %; andere Auswertungen sind weniger eindeutig, reine Aufklärungskampagnen sind kaum untersucht.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=52', 'https://www.vrc.crim.cam.ac.uk/node/1282', 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10251, 25, 11, 'ST', 'Kinder- und Jugendmedienschutz: Meldemöglichkeiten besser auffindbar machen, Schutzmaßnahmen ausbauen', '{2501}', null, 1, 2, null, 'Besser auffindbare Meldewege für junge Nutzer setzen an der geringen Meldequote an, betreffen aber nur Jugendschutz; Durchsetzung über die Landesmedienanstalt ist durch den DSA begrenzt.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=35', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10252, 25, 12, null, 'Digitales Gewaltschutzgesetz gegen digitale Gewalt, Täter-Accounts leichter sperrbar, Verbandsklage für Betroffene', '{2501,2502}', 10228, 2, 3, null, 'Sperren von Täterkonten senkten in Fallstudien Aktivität und Toxizität, Betroffene erhalten einen Rechtsweg; Ausweichen auf neue Konten oder andere Plattformen schwächt die Wirkung, die Belege sind begrenzt.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=44', 'https://cscw2021.cc.gatech.edu/?p=43', 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10253, 25, 12, null, 'Log-in-Falle: Erfassung der IP-Adresse bei Anmeldung an verdächtigen Konten, damit Stammdaten ermittelt werden können', '{2501}', 10229, 2, 3, null, 'Schließt eine Ermittlungslücke bei anonymen Konten und macht Anzeigen aussichtsreicher; zur tatsächlichen Wirkung auf Aufklärung und Abschreckung gibt es kaum Untersuchungen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=45', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10254, 25, 12, null, 'Zentralstelle für strafbare Inhalte im Internet beim Bundeskriminalamt weiter ausbauen', '{2501}', null, 1, 3, null, 'Die BKA-Zentralstelle bündelt Meldungen und Verfahren zu Online-Hass, der Bund ist zuständig; eine Wirkung auf Meldeverhalten oder Hassaufkommen ist nicht evaluiert.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=48', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10255, 25, 12, null, 'Datenschutz bei Hassdelikten: Wohnanschrift im Strafverfahren nicht mehr durch Akteneinsicht offenlegen', '{2501}', null, 1, 3, null, 'Nimmt Betroffenen die Sorge, dass Täter über die Akte ihre Anschrift erfahren, und senkt so eine Hürde für Anzeigen; die Reichweite ist eng, die Wirkung nicht untersucht.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=48', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10256, 25, 12, null, 'Volksverhetzungsparagrafen überarbeiten, um Schutzlücken bei menschenverachtender Hetze zu schließen', '{2501}', 10232, 1, 3, null, 'Neue oder klarere Straftatbestände geben Betroffenen eine Handhabe; ob sie Hass im Netz verringern, hängt von der Durchsetzung ab und ist kaum untersucht.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=48', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10257, 25, 12, null, 'Ansprechstelle für Kommunalpolitik im Deutschen Forum Kriminalprävention stärken', '{2501}', 10231, 2, 2, null, 'Beratung senkt den Aufwand für Betroffene, gegen Hass vorzugehen, Evaluationen zeigen hohe Zufriedenheit; Wirkung auf Meldungen und Anzeigen ist kaum gemessen, der Bund kann nur über Programme fördern.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=48', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10258, 25, 12, null, 'Plattformbetreiber verpflichten, illegale Inhalte zu entfernen', '{2502}', 10227, 2, 2, null, 'Löschpflichten mit Bußgeld senkten nach NetzDG-Studie Hass online und Hasskriminalität offline; die Pflicht besteht über den DSA aber schon, und eigene nationale Regeln sind durch die EU-Harmonisierung begrenzt.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=45', 'https://econpapers.repec.org/RePEc:cge:wacage:701', 'belegt', '2026-10-20', false, true, 'blind', null),
  (10259, 25, 12, null, 'Plattformen verpflichten, Algorithmen und Entscheidungsprozesse der Inhaltsdarstellung offenzulegen', '{2502}', null, 1, 1, null, 'Offenlegung von Algorithmen erleichtert Aufsicht über Plattformen, wirkt auf Hassinhalte aber nur mittelbar; Transparenzpflichten regelt weitgehend der EU-weite DSA.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=50', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10260, 25, 12, 'BE', 'Digitale Präventionsansätze gegen Hassrede und Radikalisierung, Teil einer Strategie für Zusammenhalt im Netz.', '{2503}', 10239, 2, 3, null, 'Schulische Programme gegen Cybermobbing senkten Täterschaft in einer Meta-Analyse um 10–15 %; andere Auswertungen sind weniger eindeutig, reine Aufklärungskampagnen sind kaum untersucht.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=29', 'https://www.vrc.crim.cam.ac.uk/node/1282', 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10261, 25, 12, 'BE', 'Hasskriminalität online wie offline stärker bekämpfen, Beratungsstellen stärken und Aufklärungsquoten erhöhen.', '{2501}', 10233, 2, 3, null, 'Beratung und geschulte Fachkräfte senken die Hürden, gegen Anfeindungen vorzugehen, Evaluationen zeigen hohe Zufriedenheit; belastbare Wirkungsbelege zu Meldungen fehlen.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=30', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10262, 25, 12, 'BE', 'Aufklärung, um Kinder und Frauen besser vor Cybergrooming und sexualisierter Gewalt im Netz zu schützen.', '{2503}', 10239, 2, 3, null, 'Schulische Programme gegen Cybermobbing senkten Täterschaft in einer Meta-Analyse um 10–15 %; andere Auswertungen sind weniger eindeutig, reine Aufklärungskampagnen sind kaum untersucht.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=32', 'https://www.vrc.crim.cam.ac.uk/node/1282', 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10263, 25, 12, 'MV', 'Mit Kampagnen gegen Fake News und Fehlinformationen sowie Förderung von Medienkompetenz Hass im Netz begegnen.', '{2503}', 10239, 2, 3, null, 'Schulische Programme gegen Cybermobbing senkten Täterschaft in einer Meta-Analyse um 10–15 %; andere Auswertungen sind weniger eindeutig, reine Aufklärungskampagnen sind kaum untersucht.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=44', 'https://www.vrc.crim.cam.ac.uk/node/1282', 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10264, 25, 12, 'MV', 'Sich im Bund für ein digitales Gewaltschutzgesetz mit Betroffenenrechten und Schließung von Strafverfolgungslücken einsetzen.', '{2501}', null, 2, 1, null, 'Ein digitales Gewaltschutzgesetz stärkt Betroffenenrechte und Accountsperren; das Land kann es nur im Bund anstoßen, die Wirkungsbelege sind begrenzt.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=38', 'https://cscw2021.cc.gatech.edu/?p=43', 'gemischt', '2026-10-20', false, true, 'blind', null),
