  (10267, 25, 12, 'ST', 'Medienbildung ausbauen, insbesondere zu Hass im Netz, Desinformation und gezielten Kampagnen.', '{2503}', 10239, 2, 3, null, 'Schulische Programme gegen Cybermobbing senkten Täterschaft in einer Meta-Analyse um 10–15 %; andere Auswertungen sind weniger eindeutig, reine Aufklärungskampagnen sind kaum untersucht.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=35', 'https://www.vrc.crim.cam.ac.uk/node/1282', 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10268, 25, 12, 'ST', 'Zivilgesellschaftliche Initiativen, die sich gegen Hass engagieren, verlässlich fördern.', '{2503}', 10240, 1, 3, null, 'Kann Prävention und Gegenrede stärken; der Bezug zu Anfeindungen im Netz ist unbestimmt und die Wirkung solcher Förderung kaum untersucht.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=36', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10269, 25, 13, null, 'Als rechtswidrig gemeldete Hassinhalte konsequent löschen und Accounts schneller sperren; digitales Gewaltschutzgesetz.', '{2502,2501}', 10228, 2, 3, null, 'Sperren von Täterkonten senkten in Fallstudien Aktivität und Toxizität, Betroffene erhalten einen Rechtsweg; Ausweichen auf neue Konten oder andere Plattformen schwächt die Wirkung, die Belege sind begrenzt.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=114', 'https://cscw2021.cc.gatech.edu/?p=43', 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10270, 25, 13, null, 'Medienanstalten der Länder sollen mehr Ressourcen für Löschung und Verfolgung von Hasskriminalität im Netz erhalten.', '{2502,2501}', null, 2, 2, null, 'Medienanstalten können Löschung und Strafverfolgung bei Online-Hass verbinden; die Wirkung ist kaum evaluiert, und als Landesbehörden kann der Bund sie nur über Vereinbarungen stärken.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=115', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10271, 25, 13, null, 'Strafverfolgung im digitalen Raum stärken: Login-Falle und gerichtlich angeordnete Accountsperren bei anonymen Accounts.', '{2501,2502}', null, 2, 3, null, 'Login-Falle und gerichtliche Accountsperren machen anonyme Täter verfolgbar und Konten sperrbar; Sperren wirkten in Fallstudien, Ausweichen auf neue Konten schwächt die Wirkung.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=140', 'https://cscw2021.cc.gatech.edu/?p=43', 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10272, 25, 13, null, 'Hasskriminalität gegen queere Menschen bekämpfen; Erfassung verbessern, Unterstützungsangebote und Ansprechstellen ausbauen.', '{2501}', 10231, 2, 2, null, 'Beratung senkt den Aufwand für Betroffene, gegen Hass vorzugehen, Evaluationen zeigen hohe Zufriedenheit; Wirkung auf Meldungen und Anzeigen ist kaum gemessen, der Bund kann nur über Programme fördern.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=121', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10273, 25, 13, null, 'Verbreitung von Nacktbildern gegen den Willen Betroffener grundsätzlich strafbar machen (EU-Richtlinie umsetzen).', '{2501}', 10232, 1, 3, null, 'Neue oder klarere Straftatbestände geben Betroffenen eine Handhabe; ob sie Hass im Netz verringern, hängt von der Durchsetzung ab und ist kaum untersucht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=119', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10274, 25, 13, null, 'Antisemitismusstrategie für den digitalen Raum erarbeiten.', '{2503}', null, 1, 3, null, 'Eine Strategie kann Prävention gegen antisemitischen Hass im Netz bündeln; ohne konkrete Maßnahmen ist eine Wirkung nicht abschätzbar.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=116', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10275, 25, 13, 'BE', 'Zentrale Meldestelle für digitale Gewalt soll Meldungen aufnehmen und mit den Strafverfolgungsbehörden zusammenarbeiten.', '{2501}', 10234, 2, 3, null, 'Ein zentraler Meldeweg mit Weiterleitung an Strafverfolgung setzt direkt an der geringen Meldequote an; zur Wirkung auf Meldeverhalten und Hassaufkommen gibt es kaum Studien.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=161', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10276, 25, 13, 'BE', 'Bekämpfung von Online-Kriminalität und Hasskriminalität im Netz soll gestärkt werden.', '{2501}', 10236, 1, 3, null, 'Mehr Personal, Technik und Schulung erhöhen die Chance, dass Anzeigen Folgen haben; eine Wirkung auf Meldeverhalten oder Hassaufkommen ist nicht evaluiert.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=224', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10277, 25, 13, 'BE', 'Verpflichtende Schulungen für Polizei und Justiz zu digitaler Gewalt.', '{2501}', 10236, 1, 3, null, 'Mehr Personal, Technik und Schulung erhöhen die Chance, dass Anzeigen Folgen haben; eine Wirkung auf Meldeverhalten oder Hassaufkommen ist nicht evaluiert.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=132', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10278, 25, 13, 'BE', 'Digitale Präventionsangebote wie Digital Streetwork ausbauen und Medienkompetenz fördern, um Hass früh zu erkennen.', '{2503}', 10239, 2, 3, null, 'Schulische Programme gegen Cybermobbing senkten Täterschaft in einer Meta-Analyse um 10–15 %; andere Auswertungen sind weniger eindeutig, reine Aufklärungskampagnen sind kaum untersucht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=159', 'https://www.vrc.crim.cam.ac.uk/node/1282', 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10279, 25, 13, 'MV', 'Beratungs- und Unterstützungsangebote für Opfer von Bedrohungen und Angriffen ausbauen', '{2501}', 10233, 2, 3, null, 'Beratung und geschulte Fachkräfte senken die Hürden, gegen Anfeindungen vorzugehen, Evaluationen zeigen hohe Zufriedenheit; belastbare Wirkungsbelege zu Meldungen fehlen.', 'https://gruene-mv.de/?wpdmdl=33772#page=90', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10280, 25, 13, 'MV', 'Strafverfolgung von Bedrohungen im digitalen Raum stärken, Polizei und Staatsanwaltschaften personell und technisch ausstatten', '{2501}', 10236, 1, 3, null, 'Mehr Personal, Technik und Schulung erhöhen die Chance, dass Anzeigen Folgen haben; eine Wirkung auf Meldeverhalten oder Hassaufkommen ist nicht evaluiert.', 'https://gruene-mv.de/?wpdmdl=33772#page=82', null, 'offen', '2026-10-20', false, true, 'blind', null),
