  (10282, 25, 13, 'MV', 'Regionalzentren für Demokratie stärken und Demokratiebildung in pädagogischen Ausbildungen verankern', '{2503}', 10240, 1, 3, null, 'Kann Prävention und Gegenrede stärken; der Bezug zu Anfeindungen im Netz ist unbestimmt und die Wirkung solcher Förderung kaum untersucht.', 'https://gruene-mv.de/?wpdmdl=33772#page=90', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10283, 25, 14, null, 'LSBTI-feindliche Hasskriminalität bundesweit einheitlich erfassen und verfolgen', '{2501}', 10230, 1, 2, null, 'Spezialisierte Stellen erhöhen Fallzahlen und Verfahren, eine Wirkung auf Melde- und Anzeigeverhalten ist nicht untersucht; Polizei und Staatsanwaltschaften sind überwiegend Ländersache.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=25', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10284, 25, 14, null, 'Auseinandersetzung mit Menschenfeindlichkeit im Schulunterricht intensivieren', '{2503}', null, 1, 1, null, 'Unterricht gegen Menschenfeindlichkeit ist Prävention, nennt aber keinen Bezug zum Netz; Lehrpläne regeln allein die Länder, der Bund kann es kaum umsetzen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=9', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10285, 25, 14, 'BE', 'Polizei und Staatsanwaltschaft sollen Mitglieder von Regierungen und Parlamenten nicht mehr aktiv auf mögliche Ehrdelikte im Internet hinweisen, um Strafanträge anzuregen.', '{2501}', null, 0, 3, null, 'Weniger Hinweise an Betroffene führen zu weniger Strafanträgen bei Ehrdelikten im Netz; ein Beitrag zum Schutz vor Anfeindungen ist nicht erkennbar.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=76', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10286, 25, 14, 'BE', 'Förderung von Vereinen und Monitoringstellen, die antisemitische Vorfälle unter der Strafbarkeitsgrenze dokumentieren.', '{2501}', 10234, 2, 3, null, 'Ein zentraler Meldeweg mit Weiterleitung an Strafverfolgung setzt direkt an der geringen Meldequote an; zur Wirkung auf Meldeverhalten und Hassaufkommen gibt es kaum Studien.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=79', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10287, 25, 14, 'BE', 'Aufklärung über Formen und Folgen psychischer Gewalt im Internet stärken.', '{2503}', 10239, 2, 3, null, 'Schulische Programme gegen Cybermobbing senkten Täterschaft in einer Meta-Analyse um 10–15 %; andere Auswertungen sind weniger eindeutig, reine Aufklärungskampagnen sind kaum untersucht.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=68', 'https://www.vrc.crim.cam.ac.uk/node/1282', 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10288, 25, 14, 'ST', 'Medienkompetenz stärken: Informationen prüfen, Desinformation erkennen, verantwortungsvoll kommunizieren – systematisch in Schule und Lehrkräftebildung', '{2503}', 10239, 2, 3, null, 'Schulische Programme gegen Cybermobbing senkten Täterschaft in einer Meta-Analyse um 10–15 %; andere Auswertungen sind weniger eindeutig, reine Aufklärungskampagnen sind kaum untersucht.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=25', 'https://www.vrc.crim.cam.ac.uk/node/1282', 'gemischt', '2026-10-20', false, true, 'blind', null),
  (10289, 25, 15, null, 'Ablehnung des EU-Digital-Services-Act und Rückabwicklung des NetzDG', '{2502}', null, 0, 0, null, 'Löschpflichten minderten laut NetzDG-Studie Hass online und offline, ihre Rücknahme wirkt dem Ziel entgegen; der DSA ist unmittelbar geltendes EU-Recht und kann nicht national abgelehnt werden.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=50', 'https://econpapers.repec.org/RePEc:cge:wacage:701', 'belegt', '2026-10-20', false, true, 'blind', null),
  (10290, 25, 15, null, 'Abschaffung des besonderen Strafschutzes (§ 188 StGB) für Personen des politischen Lebens', '{2501}', null, 0, 3, null, 'Die Abschaffung nimmt Betroffenen aus der Politik einen Strafschutz gegen Verleumdung; Befürworter sehen Meinungsfreiheit gestärkt, zum Schutz vor Anfeindungen trägt es nicht bei.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=133', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10291, 25, 15, 'BE', 'Öffentliche Förderung von Meldestellen beenden, die Meldungen unterhalb der Strafbarkeitsgrenze sammeln', '{2501}', 10235, 0, 3, null, 'Weniger Meldewege erschweren Betroffenen das Melden; ein Beitrag zum Schutz vor Anfeindungen ist nicht erkennbar.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=77', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10292, 25, 15, 'BE', 'Abschaffung des Strafrechtsschutzes für Politiker vor Beleidigung und Verleumdung (§ 188 StGB)', '{2501}', 10238, 0, 1, null, 'Weniger Strafschutz gibt Betroffenen weniger Handhabe gegen Anfeindungen; Kritiker sehen darin Schutz der Meinungsfreiheit, zum Ziel trägt es nicht bei. Zuständig ist der Bund.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=16', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10293, 25, 15, 'MV', 'Mit Steuern finanzierte Portale, über die Anzeigen bei Staatsanwaltschaften eingehen, werden abgelehnt.', '{2501}', 10235, 0, 3, null, 'Weniger Meldewege erschweren Betroffenen das Melden; ein Beitrag zum Schutz vor Anfeindungen ist nicht erkennbar.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=43', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10294, 25, 15, 'MV', 'Das Sonderrecht für Beleidigungen von Politikern soll abgeschafft werden.', '{2501}', 10238, 0, 1, null, 'Weniger Strafschutz gibt Betroffenen weniger Handhabe gegen Anfeindungen; Kritiker sehen darin Schutz der Meinungsfreiheit, zum Ziel trägt es nicht bei. Zuständig ist der Bund.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=43', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10295, 25, 15, 'ST', 'Rückabwicklung des Netzwerkdurchsetzungsgesetzes und Überprüfung der europäischen Digitalgesetze einfordern.', '{2501}', null, 0, 1, null, 'Rücknahme von Lösch- und Meldepflichten schwächt den Schutz vor Hassinhalten, die NetzDG-Studie fand eine Minderung von Hass; Befürworter verweisen auf Overblocking. Zuständig sind Bund und EU.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=222', 'https://econpapers.repec.org/RePEc:cge:wacage:701', 'belegt', '2026-10-20', false, true, 'blind', null),
  (10296, 25, 15, 'ST', 'Auf Rückgängigmachung der 2021 zusammengefassten Strafrechtsänderungen gegen Hasskriminalität hinwirken.', '{2501}', 10238, 0, 1, null, 'Weniger Strafschutz gibt Betroffenen weniger Handhabe gegen Anfeindungen; Kritiker sehen darin Schutz der Meinungsfreiheit, zum Ziel trägt es nicht bei. Zuständig ist der Bund.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=222', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10297, 25, 16, null, 'Beratungsprojekte für Betroffene, darunter Opferberatungen, stärker fördern und langfristig finanziell absichern.', '{2501}', 10231, 2, 2, null, 'Beratung senkt den Aufwand für Betroffene, gegen Hass vorzugehen, Evaluationen zeigen hohe Zufriedenheit; Wirkung auf Meldungen und Anzeigen ist kaum gemessen, der Bund kann nur über Programme fördern.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=51', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10298, 25, 16, null, 'Straftaten gegen Medienschaffende gesondert erfassen und von Schwerpunktstaatsanwaltschaften bearbeiten lassen.', '{2501}', 10230, 1, 2, null, 'Spezialisierte Stellen erhöhen Fallzahlen und Verfahren, eine Wirkung auf Melde- und Anzeigeverhalten ist nicht untersucht; Polizei und Staatsanwaltschaften sind überwiegend Ländersache.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=55', null, 'offen', '2026-10-20', false, true, 'blind', null),
  (10299, 25, 16, null, 'KI-erzeugte Medieninhalte kennzeichnen; Plattformen sollen für Falschinformationen und Rechtsverstöße durch solche Inhalte haften.', '{2502}', null, 1, 1, null, 'Haftung für rechtswidrige KI-Inhalte kann Plattformen zum Löschen bewegen, zielt aber vor allem auf Desinformation; Haftungsregeln für Plattformen bestimmt weitgehend die EU (DSA, KI-Verordnung).', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=55', null, 'offen', '2026-10-20', false, true, 'blind', null),
