  (10365, 25, 16, 'MV', 'Beratungs- und Unterstützungsangebote für Betroffene digitaler Gewalt ausbauen und stärken', '{2501}', 10233, 2, 3, null, 'Beratung und geschulte Fachkräfte senken die Hürden, gegen Anfeindungen vorzugehen, Evaluationen zeigen hohe Zufriedenheit; belastbare Wirkungsbelege zu Meldungen fehlen.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=14', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10366, 25, 16, 'MV', 'Hasskriminalität und diskriminierende Straftaten konsequent bekämpfen', '{2501}', 10358, 1, 2, null, 'Strafverfolgung kann Betroffenen Rückhalt geben und abschrecken; ohne konkretes Mittel (Personal, Stellen, Meldeweg) bleibt offen, was sich ändert, die Wirkung ist kaum untersucht.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=7', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10367, 25, 16, 'MV', 'Polizei und Justiz für digitale Gewalt sensibilisieren und fortbilden', '{2501}', 10236, 1, 3, null, 'Mehr Personal, Technik und Schulung erhöhen die Chance, dass Anzeigen Folgen haben; eine Wirkung auf Meldeverhalten oder Hassaufkommen ist nicht evaluiert.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=14', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10368, 25, 16, 'MV', 'Justizbeschäftigte besser vor Bedrohungen, Einschüchterung und Hasskampagnen schützen', '{2501}', null, 1, 3, null, 'Schutz vor Bedrohungen und Hasskampagnen hilft einer einzelnen Berufsgruppe; das Mittel ist unbestimmt, betrifft nur zum Teil das Netz, und eine Wirkung ist kaum untersucht.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=7', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10369, 25, 16, 'MV', 'Projekte unterstützen, die sich gegen Hass und digitale Übergriffe engagieren', '{2503}', 10240, 1, 3, null, 'Kann Prävention und Gegenrede stärken; der Bezug zu Anfeindungen im Netz ist unbestimmt und die Wirkung solcher Förderung kaum untersucht.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=14', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10370, 25, 16, 'ST', 'Spezialisierte Ansprechpersonen für Hasskriminalität in jeder Polizeibehörde und jedem Landkreis, damit Opfer von Hass ernst genommen werden.', '{2501}', 10236, 1, 3, null, 'Mehr Personal, Technik und Schulung erhöhen die Chance, dass Anzeigen Folgen haben; eine Wirkung auf Meldeverhalten oder Hassaufkommen ist nicht evaluiert.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=127', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10371, 25, 16, 'ST', 'Verfasser von Hassnachrichten vor allem im Online-Bereich vor Konsequenzen stellen.', '{2501}', 10358, 1, 2, null, 'Strafverfolgung kann Betroffenen Rückhalt geben und abschrecken; ohne konkretes Mittel (Personal, Stellen, Meldeweg) bleibt offen, was sich ändert, die Wirkung ist kaum untersucht.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=21', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10372, 25, 17, null, 'Staatlich geförderte Meldestellen für Meinungsäußerungen abschaffen und nicht mehr mit Steuergeld finanzieren', '{2501}', 10356, 0, 3, null, 'Weniger Meldewege erschweren Betroffenen das Melden; Befürworter verweisen auf Meinungsfreiheit, ein Beitrag zum Schutz vor Anfeindungen ist nicht erkennbar. Der Bund kann eigene Förderung einstellen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=39', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10373, 25, 17, null, 'Beleidigung von Personen des politischen Lebens aus dem Strafgesetzbuch (§ 188) streichen', '{2501}', 10357, 0, 3, null, 'Weniger Strafschutz gibt Betroffenen weniger Handhabe gegen Anfeindungen; Kritiker der Norm sehen darin Schutz der Meinungsfreiheit, zum Ziel trägt es nicht bei. Der Bund kann das StGB ändern.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=35', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10374, 25, 17, null, 'Polizei soll das Internet nicht nach Beleidigungen durchforsten und Hausdurchsuchungen dafür unterlassen', '{2501}', null, 0, 2, null, 'Weniger Ermittlungen zu Beleidigungen im Netz entlasten die Polizei, verringern aber die Folgen für Täter und die Aussicht für Betroffene; Polizei ist überwiegend Ländersache.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=35', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10375, 25, 17, null, 'Begriffe wie „Hass und Hetze“ klar definieren, damit zulässige Meinungen nicht als strafbar oder löschbar gelten', '{2502}', null, 0, 2, null, 'Engere Begriffe sollen zulässige Meinungen vor Löschung und Strafe schützen; Löschpflichten und Strafschutz gegen Hass werden dadurch eher schwächer, ein Beitrag zum Schutz vor Anfeindungen ist nicht erkennbar.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=39', null, 'offen', '2026-10-21', false, true, 'blind', null);

